import { readFileSync } from 'node:fs'
import { fileURLToPath, URL } from 'node:url'
import tailwindcss from '@tailwindcss/vite'
import { defineConfig } from 'vitepress'

interface CatalogItem { name: string, title: string, section: string, category: string, url: string }

// Generated by scripts/build-registry.mjs from registry/ui/*/meta.json (already sorted).
const catalog: CatalogItem[] = JSON.parse(
  readFileSync(fileURLToPath(new URL('../../registry/catalog.json', import.meta.url)), 'utf8'),
)

const SECTION_TITLES: Record<string, string> = {
  components: 'Components',
  blocks: 'Blocks',
  ai: 'AI',
  charts: 'Charts',
}

function sectionGroups(section: string) {
  const items = catalog.filter(c => c.section === section)
  const categories = [...new Set(items.map(c => c.category))]
  // A section with a single category shows as one flat group.
  if (categories.length <= 1)
    return [{ text: SECTION_TITLES[section]!, collapsed: false, items: items.map(c => ({ text: c.title, link: c.url })) }]
  return categories.map(category => ({
    text: section === 'components' ? category : `${SECTION_TITLES[section]} · ${category}`,
    collapsed: false,
    items: items.filter(c => c.category === category).map(c => ({ text: c.title, link: c.url })),
  }))
}

const gettingStarted = {
  text: 'Getting Started',
  items: [
    { text: 'Introduction', link: '/docs/' },
    { text: 'Installation', link: '/docs/installation' },
    { text: 'Theming', link: '/docs/theming' },
    { text: 'Motion Patterns', link: '/docs/motion' },
    { text: 'For AI Agents', link: '/docs/ai-agents' },
    { text: 'Changelog', link: '/changelog' },
  ],
}

const sidebar = [
  gettingStarted,
  ...Object.keys(SECTION_TITLES).flatMap(sectionGroups),
]

export default defineConfig({
  title: 'vuelix',
  description: 'Animated, copy-paste components for Vue — built on Tailwind CSS and Motion.',
  cleanUrls: true,
  sitemap: { hostname: 'https://vuelix.dev' },
  lastUpdated: true,
  head: [
    ['link', { rel: 'icon', href: '/logo.svg', type: 'image/svg+xml' }],
    ['meta', { name: 'theme-color', content: '#10b981' }],
  ],
  themeConfig: {
    logo: '/logo.svg',
    nav: [
      { text: 'Docs', link: '/docs/', activeMatch: '^/docs/' },
      { text: 'Components', link: '/components/', activeMatch: '^/components/' },
      { text: 'Blocks', link: '/blocks/', activeMatch: '^/blocks/' },
      { text: 'AI', link: '/ai/', activeMatch: '^/ai/' },
      { text: 'Charts', link: '/charts/', activeMatch: '^/charts/' },
      { text: 'Sponsors', link: '/sponsors' },
    ],
    sidebar: {
      '/docs/': sidebar,
      '/components/': sidebar,
      '/blocks/': sidebar,
      '/ai/': sidebar,
      '/charts/': sidebar,
      '/changelog': sidebar,
    },
    socialLinks: [{ icon: 'github', link: 'https://github.com/kdpisda/vuelix' }],
    search: { provider: 'local' },
    outline: [2, 3],
    footer: {
      message: 'Released under the MIT License. Built with Vue, Tailwind CSS and Motion.',
      copyright: 'Designed by <a href="https://kdpisda.in" target="_blank">Kuldeep Pisda</a>',
    },
  },
  vite: {
    // VitePress bundles Vite 5 while the workspace also has Vite 7 (for the npm package);
    // the plugin works with both, only their type declarations disagree.
    plugins: [tailwindcss() as any],
    resolve: {
      alias: {
        '@': fileURLToPath(new URL('../../registry', import.meta.url)),
      },
    },
    ssr: {
      noExternal: ['motion-v'],
    },
  },
})
